#!/usr/bin/env python3
"""Workaround for a bug in the C++ generated by STruC++ 0.6.3.

It declares variables inside a case body without opening braces, and C++
treats that as a jump over initialization:

    error: jump to case label
    note: crosses initialization of 'bool __gwv_26'

Each case label gets its body between braces. The generated code has regular
indentation, so the label body runs up to the next line with indentation less
than or equal to the label's. Remove when the compiler is fixed.
"""
from pathlib import Path
import re
import sys

target = Path(sys.argv[1])
lines = target.read_text(encoding="utf-8").splitlines()
label = re.compile(r"^(\s*)(case\s+[^:]+:|default:)\s*$")
output = []
open_indent = None  # indentation of the label whose body is open
fixes = 0

for line in lines:
    indent = len(line) - len(line.lstrip())
    content = line.strip()
    if open_indent is not None and content and indent <= open_indent:
        output.append(" " * open_indent + "}")
        open_indent = None
    match = label.match(line)
    if match:
        output.append(f"{match.group(1)}{match.group(2)} {{")
        open_indent = len(match.group(1))
        fixes += 1
        continue
    output.append(line)

if open_indent is not None:
    output.append(" " * open_indent + "}")
target.write_text("\n".join(output) + "\n", encoding="utf-8")
print(f"Case workaround applied to {fixes} labels in {target.name}")
